import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CZqXuAiL.js";const p=JSON.parse('{"title":"Admin Panel Guide","description":"Walkthrough of every Bandwidth Monitor admin page in the Pterodactyl panel — Dashboard, Nodes, Servers, Reports, Settings, and Events — with what each card, chart, and action does.","frontmatter":{"title":"Admin Panel Guide","description":"Walkthrough of every Bandwidth Monitor admin page in the Pterodactyl panel — Dashboard, Nodes, Servers, Reports, Settings, and Events — with what each card, chart, and action does."},"headers":[],"relativePath":"pterodactyl-bandwidth-monitor/user-guide/admin-panel.md","filePath":"pterodactyl-bandwidth-monitor/user-guide/admin-panel.md","lastUpdated":1785221274000}'),d={name:"pterodactyl-bandwidth-monitor/user-guide/admin-panel.md"};function s(n,e,i,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="admin-panel-guide" tabindex="-1">Admin Panel Guide <a class="header-anchor" href="#admin-panel-guide" aria-label="Permalink to &quot;Admin Panel Guide&quot;">​</a></h1><p>The panel addon adds a <strong>Bandwidth</strong> section to the Pterodactyl admin area (<code>/admin/bandwidth</code>), with six tabs: <strong>Dashboard, Nodes, Servers, Reports, Settings, Events</strong>. This page walks through each of them.</p><p>All pages require a normal Pterodactyl admin session (web auth + 2FA + admin middleware). The charts are rendered with a bundled copy of Chart.js — no external CDN calls.</p><hr><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p>Route: <code>/admin/bandwidth</code> — the landing page. Fleet overview at a glance.</p><h3 id="stat-cards" tabindex="-1">Stat cards <a class="header-anchor" href="#stat-cards" aria-label="Permalink to &quot;Stat cards&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Card</th><th>What it shows</th><th>Source</th></tr></thead><tbody><tr><td><strong>Nodes Online</strong></td><td>Online / total Pterodactyl nodes (<code>x / y</code>)</td><td>A node counts as online when its agent has registered and is heartbeating (<code>is_online</code> flag)</td></tr><tr><td><strong>Servers Monitored</strong></td><td>Total number of servers on the panel</td><td>Panel server count</td></tr><tr><td><strong>RX + TX Today</strong></td><td>Combined inbound + outbound bytes since local midnight (in the configured quota timezone)</td><td>Summed from the hourly usage rollup table</td></tr><tr><td><strong>Servers Throttled / Exceeded</strong></td><td>Servers currently throttled plus servers with at least one exceeded quota, summed across all online nodes</td><td>The <code>throttled</code> and <code>quota_exceeded</code> counters each node reports in its heartbeat</td></tr></tbody></table><p>Each card links to the relevant tab (nodes, servers, reports, events).</p><h3 id="fleet-bandwidth-chart-last-24h" tabindex="-1">Fleet Bandwidth chart (last 24h) <a class="header-anchor" href="#fleet-bandwidth-chart-last-24h" aria-label="Permalink to &quot;Fleet Bandwidth chart (last 24h)&quot;">​</a></h3><p>A stacked RX/TX line chart of the whole fleet over the last 24 hours, in hourly buckets. Loaded from the session-authed JSON endpoint <code>GET /admin/bandwidth/api/timeseries?hours=24</code>, which reads the hourly/daily rollup tables (see <a href="./../architecture/overview">Architecture</a> for how data gets there).</p><h3 id="top-10-consumers-chart-last-24h" tabindex="-1">Top 10 Consumers chart (last 24h) <a class="header-anchor" href="#top-10-consumers-chart-last-24h" aria-label="Permalink to &quot;Top 10 Consumers chart (last 24h)&quot;">​</a></h3><p>A horizontal bar chart of the ten heaviest servers by combined RX + TX bytes over the last 24 hours, loaded from <code>GET /admin/bandwidth/api/top-consumers?hours=24</code>. Both chart endpoints accept <code>hours</code> (1–2160), <code>node_id</code>, and (timeseries only) <code>server_id</code> filters.</p><h3 id="predictions-box" tabindex="-1">Predictions box <a class="header-anchor" href="#predictions-box" aria-label="Permalink to &quot;Predictions box&quot;">​</a></h3><p>The <strong>Predictions</strong> table lists servers projected to exceed an active quota before the current period ends, sorted by soonest projected exceed date. Columns: server, direction (RX/TX), period (day/week/month), quota, used so far, projected total, projected exceed date, and the exceed action that will fire.</p><p>Only servers with enforcement enabled and at least one quota above zero are considered. The result is cached for 60 seconds and capped at 10 rows on the dashboard.</p><div class="info custom-block"><p class="custom-block-title">HOW THE PREDICTION MATH WORKS</p><p>The primary signal is a <strong>linear projection</strong> over the current period:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rate_avg  = used / elapsed_seconds_in_period</span></span>
<span class="line"><span>projected = used + rate_avg * remaining_seconds_in_period</span></span></code></pre></div><p>For week and month quotas a <strong>secondary signal</strong> is added: the server&#39;s average daily usage over its last 7 daily rollup rows, extrapolated over the remaining days (<code>used + avg_daily * remaining_days</code>). A row appears if either signal crosses the quota.</p><p>When the primary projection exceeds the quota, the projected exceed date is the moment the linear trend crosses it: <code>period_start + (quota / used) * elapsed</code>. Dates are displayed in the configured quota timezone.</p></div><div class="warning custom-block"><p class="custom-block-title">PROJECTIONS ARE ESTIMATES</p><p>A linear projection assumes the current burn rate continues. A server that pushed its monthly quota in the first two days will show an early &quot;exceed date&quot; even if it then idles. Treat predictions as an early-warning signal, not a guarantee — enforcement itself is driven by real counters, not projections.</p></div><hr><h2 id="nodes" tabindex="-1">Nodes <a class="header-anchor" href="#nodes" aria-label="Permalink to &quot;Nodes&quot;">​</a></h2><p>Route: <code>/admin/bandwidth/nodes</code> — pairing and node health. Every Pterodactyl node gets a card here; a pairing token row is generated automatically the first time the page loads.</p><h3 id="node-card-fields" tabindex="-1">Node card fields <a class="header-anchor" href="#node-card-fields" aria-label="Permalink to &quot;Node card fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Status</strong> (dot)</td><td>Online / Offline, driven by registration + heartbeats. A failed health check only flips a node offline after 3 consecutive failures, so one bad probe cannot mark a healthy node down</td></tr><tr><td><strong>API URL</strong></td><td>The URL the panel uses to call the node&#39;s REST API (default port <code>8480</code>). Set automatically when the agent registers; <code>not registered</code> until then</td></tr><tr><td><strong>Agent Version</strong></td><td>Agent version reported at register/heartbeat time</td></tr><tr><td><strong>Last Seen</strong></td><td>Last successful registration or heartbeat, humanized</td></tr><tr><td><strong>Containers</strong></td><td>Managed (online) server containers, from the last heartbeat</td></tr><tr><td><strong>Throttled / Exceeded</strong></td><td>Node-local counts from the last heartbeat</td></tr></tbody></table><p>The page auto-refreshes these fields every 30 seconds via <code>GET /admin/bandwidth/nodes/poll</code> (database-backed values only — it never calls the node).</p><h3 id="card-actions" tabindex="-1">Card actions <a class="header-anchor" href="#card-actions" aria-label="Permalink to &quot;Card actions&quot;">​</a></h3><ul><li><strong>View Token</strong> — shows the node&#39;s 64-hex pairing token in a modal without rotating it. This is a POST-only endpoint, so the secret is never exposed via a browser-navigable GET. The panel stores the token bcrypt-hashed for verification plus an encrypted copy so you can re-view it.</li><li><strong>Reset Token</strong> — rotates the token. The old token is dead immediately. After a reset you must update <code>/etc/bandwidth-node/token</code> on the node and restart the agent (<code>systemctl restart bandwidth-node</code>).</li><li><strong>API URL</strong> — edit the URL the panel dials for this node. Must start with <code>http://</code> or <code>https://</code>. Leave empty to clear the override; it is repopulated at the next registration. Useful when the panel must reach the node over a different address than the one the agent auto-derived.</li><li><strong>Health</strong> — runs a live <code>GET /api/v1/health</code> probe against the agent right now and updates the card. Returns an error if the node has not registered yet.</li></ul><h3 id="install-instructions" tabindex="-1">Install instructions <a class="header-anchor" href="#install-instructions" aria-label="Permalink to &quot;Install instructions&quot;">​</a></h3><p>The <strong>Install Instructions</strong> button opens a modal with the pairing procedure: copy the token, run <code>node-module/install.sh</code> as root on the Wings host, answer the prompts (panel URL, token, listen address, port — default <code>8480</code>). The installer writes <code>/etc/bandwidth-node/config.yaml</code> and <code>/etc/bandwidth-node/token</code> (both <code>0600</code>), installs the <code>bandwidth-node</code> systemd unit, starts it, and waits for registration. The node card flips to <strong>Online</strong> once the agent registers and heartbeats.</p><div class="tip custom-block"><p class="custom-block-title">FIREWALL</p><p>The node API listens on port <code>8480</code> by default. The panel must be able to reach it (for stats pulls, limits pushes, and unthrottle calls) — open it from the panel host only. The agent calls out to the panel on its normal web port; nothing else is needed inbound.</p></div><hr><h2 id="servers" tabindex="-1">Servers <a class="header-anchor" href="#servers" aria-label="Permalink to &quot;Servers&quot;">​</a></h2><p>Route: <code>/admin/bandwidth/servers</code> — per-server limits, 25 per page.</p><h3 id="the-table" tabindex="-1">The table <a class="header-anchor" href="#the-table" aria-label="Permalink to &quot;The table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Server</strong></td><td>Name (link to the standard Pterodactyl server page) + UUID</td></tr><tr><td><strong>Node</strong></td><td>Hosting node</td></tr><tr><td><strong>Limits</strong></td><td><code>custom</code> (per-server override exists and enforcement is on), <code>disabled</code> (override exists, enforcement off), or <code>default</code> (no override — the global defaults from Settings apply)</td></tr><tr><td><strong>Speed (RX/TX)</strong></td><td>Effective speed caps in Mbps; <code>0</code> = unlimited</td></tr><tr><td><strong>Quotas (RX d/w/m)</strong></td><td>Effective inbound quotas in GiB: day / week / month; <code>0</code> = unlimited</td></tr><tr><td><strong>Quotas (TX d/w/m)</strong></td><td>Same for outbound</td></tr><tr><td><strong>On Exceed</strong></td><td><code>throttle</code>, <code>suspend</code>, or <code>none</code></td></tr></tbody></table><p>&quot;Effective&quot; means: the override row if one exists, otherwise the global defaults. There is no partial override — saving an override stores a complete set of values for that server.</p><h3 id="edit-modal" tabindex="-1">Edit modal <a class="header-anchor" href="#edit-modal" aria-label="Permalink to &quot;Edit modal&quot;">​</a></h3><p>The <strong>Edit</strong> button opens a modal with the full limits set for that server:</p><ul><li><strong>Enforce bandwidth limits for this server</strong> — master switch. Unchecked means no speed caps and no quota enforcement for this server (events and tc rules are cleared on the node).</li><li><strong>Use global defaults</strong> — deletes the per-server override; the server follows Settings again. Checking it disables the rest of the form.</li><li><strong>RX / TX speed cap (Mbps, 0 = unlimited)</strong> — hard rate caps enforced with <code>tc</code> on the server&#39;s veth.</li><li><strong>RX / TX quotas (GB, 0 = unlimited)</strong> — six fields: daily, weekly, monthly, per direction. Quotas are in <strong>GiB</strong> (1024³ bytes) and reset at calendar boundaries.</li><li><strong>On quota exceed</strong> — <code>throttle</code> (drop to the throttle speeds), <code>suspend</code> (suspend the Pterodactyl server, then hold at 1 Mbps), or <code>none</code> (record an event only).</li><li><strong>Throttle RX / TX speed (Mbps)</strong> — the speeds applied when the action is <code>throttle</code>. Minimum 1.</li></ul><p><strong>Save &amp; Push to Node</strong> validates the values (integers, speeds/quotas 0–1000000, throttle speeds 1–1000000), bumps the panel&#39;s <code>config_version</code>, and queues a limits push to the server&#39;s node when it is online. No-op saves (unchanged values) skip the bump and the push.</p><div class="info custom-block"><p class="custom-block-title">HOW SERVERS LEARN ABOUT CHANGES</p><p>Saving limits pushes the new set to the node immediately (queued job). Independently, every node sees the bumped <code>config_version</code> in the heartbeat response and pulls the full limits set itself — so a node that was offline when you saved catches up as soon as it comes back.</p></div><h3 id="unthrottle" tabindex="-1">Unthrottle <a class="header-anchor" href="#unthrottle" aria-label="Permalink to &quot;Unthrottle&quot;">​</a></h3><p>The unlock button next to <strong>Edit</strong> removes an active throttle on that server immediately, by calling <code>POST /api/v1/servers/{uuid}/unthrottle</code> on its node. The override holds until the underlying quota period resets — then normal quota evaluation resumes. It fails with an error message if the node is offline or has not registered (the call is made without retries so the page never hangs on a dead node).</p><hr><h2 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h2><p>Route: <code>/admin/bandwidth/reports</code> — usage reports and projections.</p><h3 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Filter</th><th>Effect</th></tr></thead><tbody><tr><td><strong>From / To</strong> (required)</td><td>Date range. Reversed ranges are swapped automatically; ranges are capped at 366 days to keep reports responsive</td></tr><tr><td><strong>Node</strong></td><td>Restrict to one node, or all</td></tr><tr><td><strong>Server</strong></td><td>Restrict to one server, or all</td></tr><tr><td><strong>Direction</strong></td><td>Both, RX only, or TX only (controls which series the chart draws)</td></tr><tr><td><strong>Mode</strong></td><td><code>Usage report</code> or <code>Projection</code></td></tr></tbody></table><h3 id="usage-report-mode" tabindex="-1">Usage report mode <a class="header-anchor" href="#usage-report-mode" aria-label="Permalink to &quot;Usage report mode&quot;">​</a></h3><p>Produces:</p><ul><li><strong>Four summary boxes</strong> — Total RX, Total TX, average per hour (RX + TX), and peak rates (RX / TX) observed in the range.</li><li><strong>Bandwidth chart</strong> — bucketed RX/TX series over the range. Ranges up to 7 days are shown in hourly buckets; longer ranges switch to daily buckets. Hourly and daily rollup tables are stitched at the aggregation boundary, so ranges spanning old and recent data never show gaps.</li><li><strong>Per-server totals table</strong> — RX, TX, and combined bytes per server for the range, sorted heaviest first and capped at 500 rows.</li><li><strong>Export CSV</strong> — downloads <code>bandwidth-report-&lt;from&gt;-to-&lt;to&gt;.csv</code> with columns <code>server_id, server_name, server_uuid, rx_bytes, tx_bytes, total_bytes</code>. Cell values starting with <code>=</code>, <code>+</code>, <code>-</code> or <code>@</code> are quote-prefixed to neutralize spreadsheet formula injection.</li></ul><h3 id="projection-mode" tabindex="-1">Projection mode <a class="header-anchor" href="#projection-mode" aria-label="Permalink to &quot;Projection mode&quot;">​</a></h3><p>Ignores the historical range and renders a table of <strong>current period projections</strong> per server: for each of day / week / month, the used → projected GiB for RX and TX, using the same linear math as the dashboard predictions box. Use it for capacity planning (&quot;who will blow their monthly quota at the current rate?&quot;) without waiting for the dashboard warning.</p><hr><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Route: <code>/admin/bandwidth/settings</code> — global defaults, collection, and retention. Saving bumps <code>config_version</code> and pushes the new defaults to every online node.</p><h3 id="default-limits" tabindex="-1">Default limits <a class="header-anchor" href="#default-limits" aria-label="Permalink to &quot;Default limits&quot;">​</a></h3><p>Applied to every server that has no per-server override, and prefilled by the addon&#39;s server-build integration for new servers:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>Default RX / TX speed (Mbps)</td><td><code>0</code></td><td>0 = unlimited</td></tr><tr><td>Default RX / TX quotas (GB) — daily, weekly, monthly</td><td><code>0</code></td><td>0 = unlimited; six fields</td></tr><tr><td>On quota exceed</td><td><code>throttle</code></td><td><code>throttle</code> / <code>suspend</code> / <code>none</code></td></tr><tr><td>Throttle RX / TX (Mbps)</td><td><code>5</code></td><td>Applied on exceed when action is <code>throttle</code>; minimum 1</td></tr></tbody></table><h3 id="collection-retention" tabindex="-1">Collection &amp; retention <a class="header-anchor" href="#collection-retention" aria-label="Permalink to &quot;Collection &amp; retention&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>Quota period timezone</td><td><code>UTC</code></td><td>Day/week/month quota boundaries are evaluated in this timezone — on the panel (reports, predictions) and pushed to every node in the limits payload</td></tr><tr><td>Node heartbeat interval (seconds)</td><td><code>60</code></td><td>15–3600. Sent to nodes at registration; also used as the panel-side stats poll interval</td></tr><tr><td>Hourly data retention (days)</td><td><code>90</code></td><td>Max 3650</td></tr><tr><td>Daily data retention (days)</td><td><code>730</code></td><td>Max 7300</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">TIMEZONE CHANGES MOVE QUOTA BOUNDARIES</p><p>Changing the quota timezone re-anchors what &quot;midnight&quot;, &quot;Monday 00:00&quot;, and &quot;the 1st&quot; mean for every quota counter. The node agents preserve already-accumulated counters when the period start moves backwards, but a boundary that legitimately passed is treated as a rollover. Change it during a quiet window.</p></div><hr><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><p>Route: <code>/admin/bandwidth/events</code> — the enforcement audit log, 50 rows per page, newest first.</p><h3 id="filters-1" tabindex="-1">Filters <a class="header-anchor" href="#filters-1" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><p>Type (dropdown of types actually present), direction (RX/TX), node, server, and a from/to date range. The <strong>Reset</strong> button clears all filters.</p><h3 id="event-types" tabindex="-1">Event types <a class="header-anchor" href="#event-types" aria-label="Permalink to &quot;Event types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th><th>Label color</th></tr></thead><tbody><tr><td><code>quota_exceeded</code></td><td>A quota counter reached its limit (includes direction, period, and used/quota bytes in the message)</td><td>red</td></tr><tr><td><code>throttled</code></td><td>tc rules were re-applied at throttle speed (or 1 Mbps pending suspension)</td><td>yellow</td></tr><tr><td><code>suspended</code></td><td>The panel suspended the Pterodactyl server after a node suspend callback</td><td>red</td></tr><tr><td><code>restored</code></td><td>A quota period reset (or limits were removed) and normal speeds were restored</td><td>green</td></tr><tr><td><code>speed_applied</code></td><td>A limits change actually changed the enforced speed on a running server</td><td>default</td></tr></tbody></table><p>Each row shows the time, server, node, period, direction, and a human-readable message (e.g. <code>tx month quota exceeded: 1181116006/1073741824 bytes used</code>). Events for servers that no longer exist keep their row with the server shown as <code>—</code>.</p><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><strong><a href="./api">API Reference →</a></strong> — the full panel ↔ node protocol, if you want to script against it.</li><li><strong><a href="./../architecture/overview">Architecture →</a></strong> — how data flows from veth counters to these charts.</li><li><strong><a href="./../architecture/enforcement">Enforcement →</a></strong> — exactly what happens on the node when a cap or quota bites.</li></ul>`,72)])])}const g=t(d,[["render",s]]);export{p as __pageData,g as default};
